// AssertBatchedContract runs every generated check against every declared subject.
//
//	Subjects: declare each with BatchedSubject
//	Extend:   BatchedOnPut, BatchedOnRead, BatchedOnList
//	Drop:     BatchedWithout, by the path each check reports under
func AssertBatchedContract(t *testing.T, opts ...BatchedOption) {
	t.Helper()
	cfg := newBatchedConfig(opts...)
	if len(cfg.subjects) == 0 {
		t.Fatalf("AssertBatchedContract was given no subject; declare one with " +
			"BatchedSubject(name, factory)")
	}
	for _, p := range cfg.phantoms() {
		t.Errorf("BatchedWithout(%q) declines nothing: no check here reports "+
			"under that path, so this suite asserts one thing more than its "+
			"author believes", p)
	}
	for _, s := range cfg.subjects {
		runBatchedChecks(t, cfg, s.name, s.factory, nil)
	}
}

// runBatchedChecks runs the whole contract against one subject.
//
// wrap is applied after the subject is built and seeded, so a wrapper is
// transparent to the seed and every failure it causes is its own.
func runBatchedChecks(
	t *testing.T,
	cfg *batchedConfig,
	label string,
	factory func() batchedmixins.Batched,
	wrap func(tb testing.TB, subject batchedmixins.Batched) batchedmixins.Batched,
) {
	t.Helper()
	t.Run(label, func(t *testing.T) {
		t.Parallel()

		t.Run(batchedPut, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onPut {
				cfg.run(t, string(suite.MethodID(batchedPut, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Key, cfg.Fixture.Value)
				})
			}
		})

		t.Run(batchedRead, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onRead {
				cfg.run(t, string(suite.MethodID(batchedRead, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Key)
				})
			}
		})

		t.Run(batchedList, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onList {
				cfg.run(t, string(suite.MethodID(batchedList, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap))
				})
			}
		})

		// The extra bodies of checks this run was given, each reporting under its
		// own name and dropped by it.
		//
		// The plain subject only. The wrapped pass exists to prove the double
		// faithful and the per-method checks above already do that, so running one
		// through the wrapper prices the wrapper and says nothing new about the
		// subject.
		if wrap == nil {
			for _, e := range cfg.extensions {
				if cfg.declined(e.name) {
					t.Run(e.name, func(t *testing.T) {
						t.Skipf("dropped through BatchedWithout(%q)", e.name)
					})
					continue
				}
				t.Run(e.name, func(t *testing.T) {
					t.Parallel()
					e.run(t, label, factory, cfg)
				})
			}
		}
	})
}

// BatchedOption configures a contract run.
type BatchedOption func(*batchedConfig)

// BatchedSubject declares an implementation to hold to the contract.
//
// Repeat it for every implementation that claims to satisfy the interface — an
// in-memory one, the one backed by a database, the one behind a network. Every
// check and every option is stated once and runs against all of them, which is
// what a conformance suite is for.
func BatchedSubject(name string, factory func() batchedmixins.Batched) BatchedOption {
	return func(c *batchedConfig) {
		c.subjects = append(c.subjects, namedBatchedSubject{name, factory})
	}
}

// BatchedWithClock supplies the clock every time-reading check measures on.
//
// Defaults to the real one, so an implementation that does not take a clock
// behaves as it would have. Supply a [clock.TestClock] — the same one the
// factory builds the subject with — and a budget becomes a claim about the time
// the implementation means to spend rather than about how loaded the machine
// was.
func BatchedWithClock(c clock.Clock) BatchedOption {
	return func(cfg *batchedConfig) { cfg.clock = c }
}

// BatchedWithFixture replaces the derived inputs.
func BatchedWithFixture(f BatchedFixture) BatchedOption {
	return func(c *batchedConfig) { c.Fixture = f }
}

// BatchedSeed replaces the derived seed.
//
// For an interface with no writer to seed itself through, which is the one
// input a conformance run cannot derive: a reader over an empty subject
// asserts nothing.
//
// Returning an error rather than swallowing one. A seed that failed quietly
// leaves every check after it asserting nothing and reporting success.
func BatchedSeed(fn func(ctx context.Context, subject batchedmixins.Batched) error) BatchedOption {
	return func(c *batchedConfig) {
		c.seed = fn
		c.seedIsDerived = false
	}
}

// BatchedOnPut adds a named check to Put.
func BatchedOnPut(name string, fn BatchedPutCheck) BatchedOption {
	return func(c *batchedConfig) {
		c.onPut = append(c.onPut, namedBatchedPutCheck{name, fn})
	}
}

// BatchedOnRead adds a named check to Read.
func BatchedOnRead(name string, fn BatchedReadCheck) BatchedOption {
	return func(c *batchedConfig) {
		c.onRead = append(c.onRead, namedBatchedReadCheck{name, fn})
	}
}

// BatchedOnList adds a named check to List.
func BatchedOnList(name string, fn BatchedListCheck) BatchedOption {
	return func(c *batchedConfig) {
		c.onList = append(c.onList, namedBatchedListCheck{name, fn})
	}
}

// BatchedWithout drops generated checks by the path each reports under.
//
// For a subject that legitimately violates one. Without this the only recourse
// is to stop running the suite, which costs every other check in the file — so
// a dropped check is reported as skipped rather than silently omitted.
func BatchedWithout(paths ...string) BatchedOption {
	return func(c *batchedConfig) {
		for _, p := range paths {
			c.without[p] = struct{}{}
		}
	}
}

type namedBatchedPutCheck struct {
	name string
	fn   BatchedPutCheck
}

type namedBatchedReadCheck struct {
	name string
	fn   BatchedReadCheck
}

type namedBatchedListCheck struct {
	name string
	fn   BatchedListCheck
}

type namedBatchedSubject struct {
	name    string
	factory func() batchedmixins.Batched
}

// batchedContractExtension is a body of checks a generated sibling adds through an option.
//
// A sibling declares the option and closes over whatever configures it, so
// everything that varies per run is typed and private to the file that owns it
// — this file understands only the name and the call. Nothing arrives except
// through an option, which is what keeps the set fixed before the first subtest
// starts.
type batchedContractExtension struct {
	// name is the path this reports under, and the one BatchedWithout drops
	// it by. Anything nested beneath it is the extension's own to name.
	name string

	// run takes the factory rather than a subject. One that drives sequences
	// builds a subject per iteration, and one that compares against a reference
	// needs the unseeded subject a factory returns — which
	// batchedConfig.subject is not.
	//
	// Called once per subject, in parallel, sharing the config. Anything it
	// mutates has to be built inside the call: state captured when the option
	// was declared is state two subjects write at once.
	run func(
		t *testing.T,
		subject string,
		factory func() batchedmixins.Batched,
		cfg *batchedConfig,
	)
}

type batchedConfig struct {
	Fixture  BatchedFixture
	subjects []namedBatchedSubject
	clock    clock.Clock
	seed     func(ctx context.Context, subject batchedmixins.Batched) error
	// seedIsDerived is what lets a failed seed name the right culprit. The
	// derived seed and a consumer's are the same field, and the advice for one
	// is useless for the other.
	seedIsDerived bool
	without       map[string]struct{}
	extensions    []batchedContractExtension
	onPut         []namedBatchedPutCheck
	onRead        []namedBatchedReadCheck
	onList        []namedBatchedListCheck
}

func newBatchedConfig(opts ...BatchedOption) *batchedConfig {
	c := &batchedConfig{
		Fixture: DefaultBatchedFixture(),
		clock:   clock.RealClock(),
		without: map[string]struct{}{},
	}
	// Derived: Put is classified writer, so the interface
	// populates itself and a reader has something to read.
	c.seed = func(ctx context.Context, subject batchedmixins.Batched) error {
		return subject.Put(ctx, c.Fixture.Key, c.Fixture.Value)
	}
	c.seedIsDerived = true
	for _, o := range opts {
		o(c)
	}
	return c
}

// subject builds a fresh implementation and seeds it, so every check runs
// against state no other check touched.
func (c *batchedConfig) subject(
	tb testing.TB,
	factory func() batchedmixins.Batched,
	wrap func(tb testing.TB, subject batchedmixins.Batched) batchedmixins.Batched,
) batchedmixins.Batched {
	tb.Helper()
	s := factory()
	if c.seed != nil {
		// Reported rather than ignored. A seed that silently failed would leave
		// every check after it running against an empty subject — passing, and
		// asserting nothing.
		//
		// Which seed ran decides what the message can usefully say. The derived
		// one fails for one of two reasons and both are fixable from here, so it
		// names them. A seed the caller supplied is theirs, and telling them to
		// supply one is advice they already took.
		if err := c.seed(tb.Context(), s); err != nil {
			if c.seedIsDerived {
				tb.Fatalf("seeding through Put failed: %v; "+
					"supply a value it accepts through BatchedWithFixture, or a "+
					"whole seed through BatchedSeed", err)
			} else {
				tb.Fatalf("the seed supplied through BatchedSeed failed: %v", err)
			}
		}
	}
	if wrap != nil {
		s = wrap(tb, s)
	}
	return s
}

// dropped reports whether a path was declined through BatchedWithout.
//
// Named rather than inlined because the drop set is read from two places: here,
// and by whatever registered through the seam — which reports under paths this
// file has never heard of and must answer the same question about them.
func (c *batchedConfig) declined(path string) bool {
	_, ok := c.without[path]
	return ok
}

// batchedPaths is every path this file reports a check under.
//
// The set a BatchedWithout argument has to be a member of. Declared
// rather than observed: a check that did not run is not a check that does not
// exist — an integration-only method skips without ever consulting the drop
// set, and reading that as a phantom would fail a correct suite on a machine
// with the environment unset.
//
//nolint:gochecknoglobals // the emitted check paths, read-only after init.
var batchedPaths = map[string]struct{}{}

// phantoms names every BatchedWithout path that declines nothing.
//
// A drop that drops nothing is this option's silent half: the consumer wrote
// it against a check since renamed, or never emitted for that method at all,
// and every run after reads green while asserting one thing more than its
// author believes. Extensions carry their own names — the seam reports under
// paths this file has never heard of — so they count as known too.
func (c *batchedConfig) phantoms() []string {
	known := func(p string) bool {
		if _, ok := batchedPaths[p]; ok {
			return true
		}
		for _, e := range c.extensions {
			if e.name == p {
				return true
			}
		}
		for _, on := range c.onPut {
			if string(suite.MethodID(batchedPut, on.name)) == p {
				return true
			}
		}
		for _, on := range c.onRead {
			if string(suite.MethodID(batchedRead, on.name)) == p {
				return true
			}
		}
		for _, on := range c.onList {
			if string(suite.MethodID(batchedList, on.name)) == p {
				return true
			}
		}
		return false
	}
	var out []string
	for p := range c.without {
		if !known(p) {
			out = append(out, p)
		}
	}
	slices.Sort(out)
	return out
}

// run executes one check unless it was dropped, reporting the drop rather than
// silently omitting it.
func (c *batchedConfig) run(t *testing.T, path, name string, fn func(tb testing.TB)) {
	t.Helper()
	if c.declined(path) {
		t.Run(name, func(t *testing.T) {
			t.Skipf("dropped through BatchedWithout(%q)", path)
		})
		return
	}
	t.Run(name, func(t *testing.T) {
		t.Parallel()
		fn(t)
	})
}

